//! Raw FFI bindings to WebKit + Cairo.
//!
//! Auto-generated by bindgen from WebKitGTK or WPE WebKit headers on Linux.
//! On macOS (without WebKit), stub bindings are used and the crate
//! compiles but panics at runtime.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::all)]

#[cfg(not(wpe_stub))]
include!(concat!(env!("OUT_DIR"), "/wpe_bindings.rs"));

// Stub module for macOS development — provides type names so code compiles
#[cfg(wpe_stub)]
mod stub {
    use std::ffi::c_void;

    // GLib/GObject types
    pub type GType = usize;
    pub type gboolean = i32;
    pub type gpointer = *mut c_void;
    pub type GObject = c_void;
    pub type GMainLoop = c_void;
    pub type GMainContext = c_void;
    pub type GError = StubGError;
    pub type GAsyncResult = c_void;
    pub type GCancellable = c_void;
    pub type GAsyncReadyCallback = Option<
        unsafe extern "C" fn(
            source_object: *mut GObject,
            res: *mut GAsyncResult,
            user_data: gpointer,
        ),
    >;

    #[repr(C)]
    pub struct StubGError {
        pub domain: u32,
        pub code: i32,
        pub message: *mut libc::c_char,
    }

    // GTK types
    pub type GtkWidget = c_void;
    pub type GtkWindow = c_void;
    pub type GtkContainer = c_void;
    pub type GtkOffscreenWindow = c_void;

    // WebKit types
    pub type WebKitWebView = c_void;
    pub type WebKitWebContext = c_void;
    pub type WebKitSettings = c_void;

    // Cairo types
    pub type cairo_surface_t = c_void;
    pub type cairo_t = c_void;
}

#[cfg(wpe_stub)]
#[allow(unused_imports)]
pub use stub::*;
